import { bigint, index, pgTable, text, uniqueIndex } from 'drizzle-orm/pg-core';
import { at, createdAt, id, json, searchColumns, updatedAt } from './_columns.js';
import { folders } from './knowledge.js';

export const FILE_PURPOSES = [
  'attachment',
  'knowledge',
  'record',
  'artifact',
  'export',
  'import',
  'skill',
  'avatar',
  'branding',
] as const;
export type FilePurpose = (typeof FILE_PURPOSES)[number];

/**
 * File metadata. Bytes only ever go through the storage provider; object keys are
 * generated by the server and never taken from user input. Access follows the owning
 * object (folder, conversation, base, run).
 */
export const files = pgTable(
  'files',
  {
    id: id(),
    purpose: text('purpose', { enum: FILE_PURPOSES }).notNull(),
    /** The storage provider instance that holds the bytes. */
    providerId: text('provider_id').notNull(),
    storageKey: text('storage_key').notNull(),
    name: text('name').notNull(),
    contentType: text('content_type').notNull(),
    sizeBytes: bigint('size_bytes', { mode: 'number' }).notNull().default(0),
    sha256: text('sha256'),
    status: text('status', { enum: ['pending', 'active', 'deleted'] })
      .notNull()
      .default('pending'),
    ownerId: text('owner_id'),
    /** Knowledge files: the folder they are in (null at the root of `space`). */
    folderId: text('folder_id').references(() => folders.id, { onDelete: 'set null' }),
    space: text('space', { enum: ['team', 'personal'] }),
    conversationId: text('conversation_id'),
    baseId: text('base_id'),
    runId: text('run_id'),
    expiresAt: at('expires_at'),
    meta: json<Record<string, unknown>>('meta', {}),
    /** Knowledge files: the name and the text read from it, for search. */
    ...searchColumns(),
    archivedAt: at('archived_at'),
    createdAt: createdAt(),
    updatedAt: updatedAt(),
  },
  (t) => [
    uniqueIndex('files_storage_key').on(t.storageKey),
    index('files_conversation_idx').on(t.conversationId),
    index('files_folder_idx').on(t.folderId),
    index('files_run_idx').on(t.runId),
    index('files_search_idx').using('gin', t.searchTsv),
  ],
);

export type FileRow = typeof files.$inferSelect;
export type NewFileRow = typeof files.$inferInsert;
